{"command":"python - <<'PY'
import pandas as pd, numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter
pce = pd.read_excel('/root/ERP-2025-table10.xls', header=None)
pfi = pd.read_excel('/root/ERP-2025-table12.xls', header=None)
cpi = pd.read_excel('/root/CPI.xlsx')

def annuals(df, col=1):
    out={}
    for _,r in df.iterrows():
        lab = r[0]
        if isinstance(lab,str):
            s=lab.strip()
            if s.endswith('.') and ':' not in s:
                try: out[int(s[:-1])] = float(r[col])
                except: pass
    return out

def q2024_avg(df,col=1):
    vals=[]
    started=False
    for _,r in df.iterrows():
        s=str(r[0]).strip()
        if s.startswith('2024: I.'):
            started=True
            vals.append(float(r[col]))
        elif started:
            if s.startswith('II.') or s.startswith('III') or s.startswith('IV.'):
                # include only numeric quarter rows before notes
                try:
                    vals.append(float(r[col]))
                except:
                    pass
            else:
                break
    return sum(vals)/len(vals)

pce_a=annuals(pce); pfi_a=annuals(pfi)
pce_a[2024]=q2024_avg(pce)
pfi_a[2024]=q2024_avg(pfi)
print(pce_a[2024], pfi_a[2024])
years=range(1973,2025)
df=pd.DataFrame({'pce_nom':[pce_a[y] for y in years],'pfi_nom':[pfi_a[y] for y in years]},index=years)
df=df.join(cpi.set_index('Year'))
df['pce_real']=df.pce_nom/df.CPI_2024
df['pfi_real']=df.pfi_nom/df.CPI_2024
cy1,_=hpfilter(np.log(df.pce_real), lamb=100)
cy2,_=hpfilter(np.log(df.pfi_real), lamb=100)
print(np.corrcoef(cy1,cy2)[0,1])
PY"}
